INSERT INTO `messages` (`id`, `conversation_id`, `role`, `content`, `created_at`, `model`, `prompt_tokens`, `completion_tokens`, `total_tokens`, `image_url`, `feedback`, `is_deleted`) VALUES
('00c10bd6-be5f-4ed0-977f-c5a0fea25f32', '2cb871c4387712e5695586b348ec8c20', 'assistant', 'The current Prime Minister of the United Kingdom as of 2023 was Rishi Sunak, but it\'s important to note that political positions can change. As of early 2024, Boris Johnson had been serving a second term as Prime Minister until his resignation in March 2022 and then elected again by Parliament in May 2022.\n\nFor the most accurate information about the current Prime Minister of the United Kingdom, I recommend checking recent news sources or official government websites.', '2026-10-21 00:08:03', 'nobrain1.0:latest', 280, 104, 384, NULL, NULL, 1),
