('3c0b2426-0a7a-4427-aca3-6388b0cbf4a3', 'aedaafe8f1f7f8d8aac915ee886ae6ef', 'assistant', 'আপনি আজকে প্রশ্নটি ভাষণে শুনেছিলেন, এখন মামা 2026 সালের বর্তমান খবর।\n\nআপনি আজকে প্রশ্নটি ভাষণে শুনেছিলেন, এখন মামা 2026 সালের বর্তমান খবর।\n\n---\n**🌐 Verified with Google Search:**\n- [youtube.com](https://www.youtube.com/watch?v=hP8JbuRrdwk)\n- [facebook.com](https://www.facebook.com/RadioMithila.Net/videos/%E0%A6%AE%E0%A6%BE%E0%A6%AE%E0%A6%BE-%E0%A6%AD%E0%A6%BE%E0%A6%97%E0%A7%8D%E0%A6%A8%E0%A7%87%E0%A6%B0-%E0%A6%96%E0%A7%9F%E0%A6%B0%E0%A6%BE%E0%A6%A4%E0%A6%BF-%E0%A6%A8%E0%A6%BF%E0%A6%B0%E0%A7%8D%E0%A6%AC%E0%A6%BE%E0%A6%9A%E0%A6%A8-%E0%A7%A8%E0%A7%A6%E0%A7%A8%E0%A7%AC/3249883468504657/)\n- [youtube.com](https://www.youtube.com/watch?v=0Mqjqva_VIw)\n- [facebook.com](https://www.facebook.com/Fansofsajeebwazed/videos/%E0%A6%AE%E0%A6%BE%E0%A6%AE%E0%A6%BE-%E0%A6%AD%E0%A6%BE%E0%A6%97%E0%A7%8D%E0%A6%A8%E0%A7%87%E0%A6%B0-%E0%A6%96%E0%A7%9F%E0%A6%B0%E0%A6%BE%E0%A6%A4%E0%A6%BF-%E0%A6%A8%E0%A6%BF%E0%A6%B0%E0%A7%8D%E0%A6%AC%E0%A6%BE%E0%A6%9A%E0%A6%A8-%E0%A7%A8%E0%A7%A6%E0%A7%A8%E0%A7%AC/920198397051037/)', '2026-10-21 15:23:34', 'nobrain1.0:latest', 1282, 140, 1422, NULL, NULL, 1),
