0, \"colorToken\": \"orange\" },\n    { \"type\": \"shape\", \"shape\": \"circle\", \"x\": 850, \"y\": 900, \"size\": 12, \"colorToken\": \"green\" },\n    { \"type\": \"shape\", \"shape\": \"circle\", \"x\": 620, \"y\": 1150,\"size\": 18, \"colorToken\": \"gold-400\" },\n\n    { \"type\": \"shape\", \"shape\": \"pill\", \"name\": \"Eyebrow Badge\", \"x\": 80, \"y\": 120, \"width\": 260, \"height\": 48, \"colorToken\": \"brand-accent\", \"borderRadius\": 999 },\n    { \"type\": \"icon\", \"icon\": \"Zap\", \"x\": 98, \"y\": 132, \"size\": 24, \"colorToken\": \"white\" },\n    { \"type\": \"text\", \"content\": \"FLASH SALE\", \"x\": 140, \"y\": 136, \"fontSize\": 18, \"fontWeight\": 800, \"colorToken\": \"white\" },\n\n    { \"type\": \"text\", \"content\": \"DHA̱MAKA\\nSALE\", \"x\": 80, \"y\": 190, \"width\": 920, \"fontSize\": 84, \"fontWeight\": 800, \"lineHeight\": 1.15, \"colorToken\": \"white\" },\n\n    { \"type\": \"text\", \"content\": \"Up to 70% OFF on headphones, smartphones & gaming laptops. Grab it before it’s gone!\", \"x\": 80, \"y\": 410, \"width\": 900, \"fontSize\": 24, \"fontWeight\": 400, \"lineHeight\": 1.35, \"colorToken\": \"cloud\" },\n\n    { \"type\": \"shape\", \"shape\": \"rectangle\", \"name\": \"Hero Frame\", \"x\": 80, \"y\": 470, \"width\": 920, \"height\": 720, \"colorToken\": \"stone\", \"borderRadius\": 28 },\n    { \"type\": \"image\", \"name\": \"Hero Image\", \"imageUrl\": \"https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=1200&q=80\", \"x\": 90, \"y\": 480, \"width\": 900, \"height\": 700, \"borderRadius\": 24, \"fit\": \"cover\" },\n\n    { \"type\": \"shape\", \"shape\": \"pill\", \"name\": \"Discount Badge\", \"x\": 80, \"y\": 1230, \"width\": 440, \"height\": 64, \"colorToken\": \"ember-500\", \"borderRadius\": 16 },\n    { \"type\": \"icon\", \"icon\": \"Percent\", \"x\": 104, \"y\": 1248, \"size\": 26, \"colorToken\": \"white\" },\n    { \"type\": \"text\", \"content\": \"UP TO 70% OFF