('e215ed0d-a978-463f-aeb4-53927d5aec79', 'ac1c1ce4ce8e163a46bafb4e13021563', 'user', 'মামা, আমার নতুন ক্লাউড ও এআই স্টার্টআপ \'SYNAPSE AI\'-এর জন্য একটি আল্ট্রা-মডার্ন লোগো ডিজাইন করে দাও। ব্যাকগ্রাউন্ড হবে ডিপ ওবসিডিয়ান ব্ল্যাক, আর লোগো মার্কে থাকবে নিয়ন সায়ান ও এমেরাল্ড প্রিজম গ্রেডিয়েন্ট শেপ। গোল্ডেন রেশিও মেনটেইন করে ক্যানভাসে রেডি করে দাও।', '2026-10-21 17:43:18', 'qwen2.5:1.5b', 65, 0, 0, NULL, NULL, 1),
('e74ca760-c2d9-4ad4-9062-3d4569a30475', 'ea4de9782d9db0eba0330413ea2822ac', 'assistant', 'আপনি প্রথম এই শিক্ষকদের জীবনস্থল মতে অভিহিত করা গান \"মামা\" ১৯৭৬-এর প্রথম সংখ্যা একটি। আপনি জয়লাভ করেছিলেন তাই, নতুমাণি খবরগোষ্ঠীর মতে \"জয়\" ১৯৬৪-এর সমস্ত জয়।\n\nআপনার শিক্ষা, আপনার ভালবাসি, আপনার খবরগোষ্ঠীতে \"জয়\" ১৯৬৪-এর জয়।\n\nআমি এই শিক্ষকদের মতান্ত্রণ, আপনার ভালবাসা ও খবরগোষ্ঠীর পছন্দের জন্য \"মামা\" ১৯৬৪-এর শিক্ষকদের গান।\n\n---\n**🌐 Verified with Google Search:**\n- [youtube.com](https://www.youtube.com/watch?v=tq_ed1PXTsc)\n- [facebook.com](https://www.facebook.com/JamunaEntertainment/posts/%E0%A7%A8%E0%A7%A6%E0%A7%A8%E0%A7%AC-%E0%A6%B8%E0%A6%BE%E0%A6%B2%E0%A7%87%E0%A6%B0-%E0%A6%AE%E0%A6%BE%E0%A6%AE%E0%A6%BE-%E0%A6%85%E0%A7%8D%E0%A6%AF%E0%A6%BE%E0%A6%93%E0%A7%9F%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A1%E0%A6%B8-%E0%A6%8F%E0%A6%B0-%E0%A6%AE%E0%A6%A8%E0%A7%8B%E0%A6%A8%E0%A7%9F%E0%A6%A8-%E0%A6%A4%E0%A6%BE%E0%A6%B2%E0%A6%BF%E0%A6%95%E0%A6%BE%E0%A7%9F-%E0%A6%8F%E0%A6%97%E0%A6%BF%E0%A7%9F%E0%A7%87-%E0%A6%B0%E0%A7%9F%E0%A7%87%E0%A6%9B%E0%A7%87-%E0%A6%95%E0%A7%87-%E0%A6%AA%E0%A6%AA-%E0%A6%AC%E0%A7%8D%E0%A6%AF%E0%A6%BE%E0%A6%A8%E0%A7%8D%E0%A6%A1-%E0%A6%AC%E0%A6%BF%E0%A6%9F%E0%A6%BF%E0%A6%8F%E0%A6%B8-%E0%A7%A7/1127964473426683/)\n- [youtube.com](https://www.youtube.com/watch?v=0Mqjqva_VIw)\n- [facebook.com](https://www.facebook.com/zia1789/videos/%E0%A6%AE%E0%A6%BE%E0%A6%AE%E0%A6%BE-%E0%A6%AD%E0%A6%BE%E0%A6%87%E0%A6%97%E0%A7%8D%E0%A6%A8%E0%A6%BE-%E0%A6%AD%E0%A7%8B%E0%A6%9F-%E0%A7%A8%E0%A7%A6%E0%A7%A8%E0%A7%AC/2267665737388260/)', '2026-10-21 15:23:01', 'nobrain1.0:latest', 1457, 350, 1807, NULL, NULL, 1),
